import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import path from 'node:path';

export function bootstrapContentId(root) {
  const hash = createHash('sha256');
  const generated = new Set();
  for (const entry of readdirSync(path.join(root, 'packages'), { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const directory = `packages/${entry.name}`;
    const manifestFile = path.join(root, directory, 'package.json');
    if (!existsSync(manifestFile)) continue;
    const manifest = JSON.parse(readFileSync(manifestFile, 'utf8'));
    for (const name of ['dist', 'artifacts', 'test-results', 'playwright-report'])
      generated.add(`${directory}/${name}`);
    if (manifest.starter?.runtime === 'worker')
      for (const name of ['.cloudflare', '.wrangler', 'src/routeTree.gen.ts'])
        generated.add(`${directory}/${name}`);
    if (manifest.starter?.runtime === 'desktop')
      for (const name of [
        'src-tauri/target',
        'src-tauri/icons',
        'src-tauri/gen',
        'src-tauri/permissions/autogenerated',
      ])
        generated.add(`${directory}/${name}`);
  }
  const walk = (directory, prefix) =>
    readdirSync(directory, { withFileTypes: true })
      .flatMap((entry) => {
        const relative = `${prefix}/${entry.name}`;
        if (entry.name === 'node_modules' || generated.has(relative)) return [];
        if (entry.isSymbolicLink()) throw new Error(`Unexpected input symlink: ${relative}`);
        return entry.isDirectory() ? walk(path.join(directory, entry.name), relative) : [relative];
      })
      .sort();
  for (const directory of ['tools', 'docs', '.agents', '.github', 'packages'])
    if (existsSync(path.join(root, directory)))
      for (const file of walk(path.join(root, directory), directory)) {
        hash.update(`${file}\0`);
        hash.update(readFileSync(path.join(root, file)));
      }
  for (const file of [
    'package.json',
    'pnpm-lock.yaml',
    'pnpm-workspace.yaml',
    'mise.toml',
    'mise.security.toml',
    'mise.o11y.toml',
    'tsconfig.json',
    'vite.config.ts',
    '.template.json',
    'AGENTS.md',
    'README.md',
    'CLAUDE.md',
    'knip.ts',
    '.gitignore',
    '.gitattributes',
    '.semgrepignore',
    'renovate.json',
    'LICENSE',
  ])
    if (existsSync(path.join(root, file))) {
      hash.update(file);
      hash.update(readFileSync(path.join(root, file)));
    }
  return hash.digest('hex');
}

